from rllab.worlds import make

# `rllab.worlds.make` the attribute is the function; the module is reached through importlib.
MAKE_MODULE = importlib.import_module("rllab.worlds.make")


class Recorder:
    """Stands in for a world class: records the overrides it was built with."""

    def __init__(self, **overrides: int | float) -> None:
        if "lives" in overrides:
            raise ValueError("unknown override 'lives' of snake")
        self.overrides = overrides


class OtherRecorder(Recorder):
    """A second stand-in, so each name is seen to pick its own class."""


@pytest.fixture
def stand_ins(monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.setattr(MAKE_MODULE, "Snake", Recorder)
    monkeypatch.setattr(MAKE_MODULE, "CheckDiscrete", OtherRecorder)


@pytest.mark.usefixtures("stand_ins")
def test_snake_names_the_snake_class() -> None:
    world = make("snake")
    assert type(world) is Recorder


@pytest.mark.usefixtures("stand_ins")
def test_check_discrete_names_the_corridor_class() -> None:
    world = make("check-discrete")
    assert type(world) is OtherRecorder


@pytest.mark.usefixtures("stand_ins")
def test_overrides_pass_to_the_world_unchanged() -> None:
    world = make("snake", max_steps=5, food=2.5)
    assert isinstance(world, Recorder)
    assert world.overrides == {"max_steps": 5, "food": 2.5}


